# Generate positions in diagonal traversal order (main diagonals first)
def diag_order_positions(n=3):
    positions = []
    for k in range(-n+1, n*2-1):
        # For each diagonal sum k = r + c
        min_r = max(0, k - (n-1))
        max_r = min(n-1, k)
        for r in range(min_r, max_r + 1):
            c = k - r
            if 0 <= c < n:
                positions.append((r, c))
    return positions

